@@ -0,0 +1,70 @@
+#!/usr/bin/env bash
+# F7 contract: `run --model fast` -- QEMU-only, transparent passthrough.
+# Three layers:
+#
+#   1. run-test (unit, fast): passthrough_argv fills the qemu `standalone`
+#      invoke template ({bin}/{elf}) and appends the post-`--` engine args
+#      verbatim -- including a `-gdb tcp::N -S` gdbstub. Pure, no spawn.
+#   2. CLI error paths (no engine needed): missing --model, unknown model,
+#      missing ELF, an extra positional, and engine!=qemu each exit 2 with a
+#      clear message.
+#   3. real passthrough (needs built qemu + a fixture): launch
+#      `run --model fast ELF -- -gdb tcp::PORT -S`; the gdbstub port opens and
+#      qemu halts at reset -- the done-when "port opens, halts, debugger
+#      connects". exec_passthrough's exit-code propagation is already covered
+#      by the F5 infra test (and observed here only indirectly).
+set -uo pipefail
+
+SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
+ROOT=$(cd -- "$SCRIPT_DIR/../.." && pwd)
+. "$SCRIPT_DIR/../lib/log.sh"
+
+BIN="$ROOT/build/andes-sim"
+RUNTEST="$ROOT/build/driver/andes-sim-run-test"
+
+bash "$ROOT/scripts/build_driver.sh" >/dev/null 2>&1 || fail "build_driver.sh failed"
+
+# 1. unit: the argv-assembly contract carries the passthrough behavior
+[ -x "$RUNTEST" ] || fail "missing unit-test binary: $RUNTEST"
+"$RUNTEST" || fail "run unit tests (passthrough_argv) failed"
+
+# assert `$BIN run ...` exits with $1 and its combined output matches regex $2
+expect_rc_match() {
+  local want_rc="$1" re="$2"; shift 2
+  local out rc
+  out=$("$@" 2>&1 </dev/null); rc=$?
+  [ "$rc" -eq "$want_rc" ] || fail "rc=$rc want $want_rc for [$*]: $out"
+  echo "$out" | grep -Eq "$re" || fail "output missing /$re/ for [$*]: $out"
+}
+
+# 2. CLI error paths (deterministic; no qemu)
+expect_rc_match 2 'model .* is required'    "$BIN" run
+expect_rc_match 2 "unknown model 'bogus'"    "$BIN" run --model bogus p.elf
+expect_rc_match 2 'missing ELF'              "$BIN" run --model fast
+expect_rc_match 2 'engine args go after --'  "$BIN" run --model fast a.elf b.elf
+expect_rc_match 2 "engine must be 'qemu'"    "$BIN" run --model fast --engine verilator:x p.elf
+
+# 3. real passthrough: a frozen-at-reset gdbstub port opens (guarded on artifacts)
+QEMU="${VSIM_QEMU:-$ROOT/build/qemu/qemu-system-riscv64}"
+ELF="$ROOT/tests/fixtures/handoff_roundtrip.elf"
+if [ -x "$QEMU" ] && [ -f "$ELF" ]; then
+  PORT=$(( 40000 + (RANDOM % 20000) ))
+  BG=""
+  cleanup() { [ -n "${BG:-}" ] && kill "$BG" 2>/dev/null; pkill -f "tcp::$PORT" 2>/dev/null; true; }
+  trap cleanup EXIT
+  # -S halts the cpu at reset, so the stub listens regardless of the ELF body.
+  "$BIN" run --model fast "$ELF" -- -gdb "tcp::$PORT" -S </dev/null >/dev/null 2>&1 &
+  BG=$!
+  opened=0
+  for _ in $(seq 1 40); do
+    if timeout 1 bash -c ">/dev/tcp/127.0.0.1/$PORT" 2>/dev/null; then opened=1; break; fi
+    sleep 0.25
+  done
+  cleanup; trap - EXIT; wait "$BG" 2>/dev/null
+  [ "$opened" -eq 1 ] || fail "fast passthrough: gdbstub port $PORT never opened"
+  echo "[ok] real fast passthrough: qemu gdbstub halted + listening on :$PORT"
+else
+  echo "[skip] real fast run: qemu and/or fixture not built ($QEMU / $ELF)"
+fi
+
+ok "F7 run --model fast"

1	// EngineDescriptor: the parsed result of an engine's `--describe` (or its
2	// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
3	// future engines (alioth, sid) speak to join the framework -- see
4	// docs/engine_interface.md. The framework keeps zero per-engine code; every
5	// capability it needs comes from here.
6	#ifndef ANDES_SIM_ENGINE_DESCRIPTOR_HPP
7	#define ANDES_SIM_ENGINE_DESCRIPTOR_HPP
8	
9	#include <string>
10	#include <string_view>
11	#include <vector>
12	
13	#include "json.hpp"
14	
15	namespace andes_sim {
16	
17	// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
18	// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
19	// plan executor (F6).
20	struct EngineInvoke {
21	  std::string role;
22	  std::vector<std::string> argv;
23	};
24	
25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // 0 = not applicable
30	  long xlen = 0;
31	  std::vector<std::string> triggers;    // csr | pc | icount | simpoint
32	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
33	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
34	  std::vector<EngineInvoke> invoke;     // argv template per role
35	  std::string result;                   // stderr:<re> | state.mcycle
36	
37	  // Filled by the registry, not present in the JSON:
38	  std::string bin_path;                 // resolved path to the binary
39	  std::string source;                   // built-in | --describe | sidecar
40	
41	  const std::vector<std::string>* invoke_for(std::string_view role) const {
42	    for (const EngineInvoke& iv : invoke)
43	      if (iv.role == role) return &iv.argv;
44	    return nullptr;
45	  }
46	};
47	
48	// Build a descriptor from parsed JSON. Returns "" on success or an error
49	// message naming the first problem (id and type are required).
50	inline std::string descriptor_from_json(const json::Value& v,
51	                                        EngineDescriptor& out) {
52	  if (!v.is_object()) return "descriptor is not a JSON object";
53	
54	  const json::Value* id = v.find("id");
55	  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
56	  out.id = id->as_string();
57	
58	  const json::Value* type = v.find("type");
59	  if (!type || !type->is_string()) return "missing string 'type'";
60	  out.type = type->as_string();
61	
62	  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
63	  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
64	  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
65	  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
66	  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
67	  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
68	  if (const json::Value* x = v.find("result")) out.result = x->as_string();
69	
70	  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
71	    for (size_t k = 0; k < inv->keys.size(); ++k)
72	      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
73	  }
74	  return "";
75	}
76	
77	}  // namespace andes_sim
78	
79	#endif  // ANDES_SIM_ENGINE_DESCRIPTOR_HPP
